import std/string (chars)

pure func balanceChars(cs: [string], count: int) -> bool =
  match cs {
    [] => count == 0,
    c :: rest =>
      if c == "(" then balanceChars(rest, count + 1)
      else if c == ")" then
        if count == 0 then false else balanceChars(rest, count - 1)
      else balanceChars(rest, count)
  }

export pure func isBalanced(s: string) -> bool =
  balanceChars(chars(s), 0)

export func main() -> () ! {IO} {
  println(show(isBalanced("(())")));
  println(show(isBalanced("(()")));
  println(show(isBalanced("())()")));
  println(show(isBalanced("()(())")))
}

