def is_balanced(text: str) -> bool:
    counter = 0
    for char in text:
        if char == '(':
            counter += 1
        elif char == ')':
            counter -= 1

        if counter < 0:
            return False

    return counter == 0

def main() -> None:
    test_cases = ["(())", "(()", "())()", "()(())"]

    for test in test_cases:
        result = is_balanced(test)
        print("true" if result else "false")

if __name__ == "__main__":
    main()

