type Config = {app_name: string, version: string, port: int, featureCount: int}

pure func countDots(s: string) -> int =
  length(filter(func(c: string) -> bool { c == "." }, chars(s)))

pure func validateConfig(appName: string, version: string, port: int, features: [Json]) -> Option[Config] =
  if port >= 1024 && port <= 65535 && countDots(version) == 2 && length(features) > 0
  then Some({app_name: appName, version: version, port: port, featureCount: length(features)})
  else None

func parseConfig(s: string) -> Option[Config] =
  match decode(s) {
    Ok(obj) => match getString(obj, "app_name") {
      Some(appName) => match getString(obj, "version") {
        Some(version) => match getInt(obj, "port") {
          Some(port) => match getArray(obj, "features") {
            Some(features) => validateConfig(appName, version, port, features),
            None => None
          },
          None => None
        },
        None => None
      },
      None => None
    },
    Err(_) => None
  }

export func main() -> () ! {IO, FS} {
  let json = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  writeFile("app_config.json", json);
  let content = readFile("app_config.json");
  match parseConfig(content) {
    Some(cfg) => {
      let msg = "Loaded " ++ cfg.app_name ++ " v" ++ cfg.version ++ " on port " ++ show(cfg.port) ++ " with " ++ show(cfg.featureCount) ++ " features";
      println(msg)
    },
    None => println("Invalid configuration")
  }
}

