import json
from pathlib import Path
from typing import Dict, Any, List

def create_initial_config(file_path: Path) -> None:
    config_data = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"]
    }
    with file_path.open('w', encoding='utf-8') as f:
        json.dump(config_data, f, indent=4)

def validate_config(config: Dict[str, Any]) -> None:
    port = config.get("port")
    if not isinstance(port, int) or not (1024 <= port <= 65535):
        raise ValueError(f"Invalid port: {port}. Must be between 1024 and 65535.")

    version = config.get("version")
    if not isinstance(version, str) or version.count(".") != 2:
        raise ValueError(f"Invalid version format: {version}. Must be X.Y.Z.")

    features = config.get("features")
    if not isinstance(features, list) or len(features) == 0:
        raise ValueError("Features list must be a non-empty list.")

def load_config(file_path: Path) -> Dict[str, Any]:
    if not file_path.exists():
        raise FileNotFoundError(f"Config file not found: {file_path}")

    with file_path.open('r', encoding='utf-8') as f:
        config = json.load(f)

    validate_config(config)
    return config

def main() -> None:
    config_path = Path("app_config.json")

    try:
        create_initial_config(config_path)
        config = load_config(config_path)

        app_name = config["app_name"]
        version = config["version"]
        port = config["port"]
        feature_count = len(config["features"])

        print(f"Loaded {app_name} v{version} on port {port} with {feature_count} features")

    except (ValueError, json.JSONDecodeError, OSError) as e:
        print(f"Configuration Error: {e}")

if __name__ == "__main__":
    main()

