module benchmark/solution

import std/fs (readFile, writeFile)
import std/string (split, trim, contains, stringToInt)
import std/json (encode, ja, jo, kv, js, jnum)
import std/option (Option, Some, None)
import std/list (length)
import std/math (intToFloat)

type User = {name: string, age: int, email: string}

pure func validateHeaders(headers: [string]) -> bool =
  match headers {
    "name" :: "age" :: "email" :: [] => true,
    _ => false
  }

pure func parseUserRow(fields: [string]) -> Option[User] =
  match fields {
    name :: ageText :: email :: [] =>
      match stringToInt(trim(ageText)) {
        Some(age) => {
          let cleanName = trim(name);
          let cleanEmail = trim(email);
          if age > 0 && contains(cleanEmail, "@")
          then Some({name: cleanName, age: age, email: cleanEmail})
          else None
        },
        None => None
      },
    _ => None
  }

pure func collectValidRows(rows: [string]) -> [User] =
  match rows {
    [] => [],
    row :: rest => {
      let cleaned = trim(row);
      if cleaned == "" then collectValidRows(rest)
      else {
        let fields = split(cleaned, ",");
        match parseUserRow(fields) {
          Some(user) => user :: collectValidRows(rest),
          None => collectValidRows(rest)
        }
      }
    }
  }

pure func usersToJson(users: [User]) -> [Json] =
  match users {
    [] => [],
    user :: rest =>
      jo([
        kv("name", js(user.name)),
        kv("age", jnum(intToFloat(user.age))),
        kv("email", js(user.email))
      ]) :: usersToJson(rest)
  }

export func main() -> () ! {IO, FS} {
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com";
  writeFile("users.csv", csvContent);
  let content = readFile("users.csv");
  let lines = split(trim(content), "\n");
  match lines {
    [] => {
      writeFile("users.json", "[]");
      println("Converted 0 valid rows to users.json")
    },
    headerLine :: rowLines => {
      let headers = split(trim(headerLine), ",");
      let users = if validateHeaders(headers) then collectValidRows(rowLines) else [];
      let jsonText = encode(ja(usersToJson(users)));
      writeFile("users.json", jsonText);
      println("Converted " ++ show(length(users)) ++ " valid rows to users.json")
    }
  }
}

