from typing import Generic, TypeVar, Callable, Any

T = TypeVar("T")
U = TypeVar("U")

class Result(Generic[T]):
    def and_then(self, func: Callable[[T], "Result[U]"]) -> "Result[U]":
        raise NotImplementedError

class Ok(Result[T]):
    def __init__(self, value: T) -> None:
        self.value = value

    def and_then(self, func: Callable[[T], "Result[U]"]) -> "Result[U]":
        return func(self.value)

class Err(Result[T]):
    def __init__(self, message: str) -> None:
        self.message = message

    def and_then(self, func: Callable[[T], "Result[U]"]) -> "Result[U]":
        return Err(self.message)

def validate_age(age: int) -> Result[int]:
    if 0 <= age <= 150:
        return Ok(age)
    return Err("Age out of range")

def calculate_retirement_years(age: int) -> Result[int]:
    if age < 65:
        return Ok(65 - age)
    return Err("Already retired")

def process_age(age: int) -> None:
    # Chain operations: validate_age -> calculate_retirement_years
    result = validate_age(age).and_then(calculate_retirement_years)

    if isinstance(result, Ok):
        print(f"Years to retirement: {result.value}")
    elif isinstance(result, Err):
        print(f"Error: {result.message}")

def main() -> None:
    test_cases = [30, 70, -5]
    for age in test_cases:
        process_age(age)

if __name__ == "__main__":
    main()

