from enum import Enum, auto

class Status(Enum):
    PENDING = auto()
    IN_PROGRESS = auto()
    COMPLETED = auto()

def describe_status(status: Status) -> str:
    if status is Status.PENDING:
        return "Waiting to start"
    elif status is Status.IN_PROGRESS:
        return "Currently working"
    elif status is Status.COMPLETED:
        return "All done"
    else:
        # Ensures exhaustiveness at runtime and for static analysis tools
        raise ValueError(f"Unhandled status variant: {status}")

def main() -> None:
    statuses = [Status.PENDING, Status.IN_PROGRESS, Status.COMPLETED]

    for status in statuses:
        print(describe_status(status))

if __name__ == "__main__":
    main()

