from dataclasses import dataclass
from abc import ABC, abstractmethod

# 1. Define expression AST data types
class Expr(ABC):
    """Base class for expression nodes."""
    pass

@dataclass
class Num(Expr):
    value: int

@dataclass
class Add(Expr):
    left: Expr
    right: Expr

@dataclass
class Mul(Expr):
    left: Expr
    right: Expr

# 2. Implement eval function
def eval_expr(expr: Expr) -> int:
    """Evaluates an expression AST to an integer."""
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Add):
        return eval_expr(expr.left) + eval_expr(expr.right)
    elif isinstance(expr, Mul):
        return eval_expr(expr.left) * eval_expr(expr.right)
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")

def main() -> None:
    # 3. Construct expression: (3 + 4) * (2 + 5)
    # AST: Mul(Add(Num(3), Num(4)), Add(Num(2), Num(5)))
    expression = Mul(
        Add(Num(3), Num(4)),
        Add(Num(2), Num(5))
    )

    # Evaluate
    result = eval_expr(expression)

    # 4. Print the result
    print(result)

if __name__ == "__main__":
    main()

