pure func subst(t: Term, target: string, replacement: Term) -> Term {
  match t {
    TVar(name) => if name == target then replacement else TVar(name),
    TLam(param, body) => if param == target then TLam(param, body) else TLam(param, subst(body, target, replacement)),
    TApp(f, arg) => TApp(subst(f, target, replacement), subst(arg, target, replacement))
