from abc import ABC
from dataclasses import dataclass

class Term(ABC):
    """Abstract base class for lambda calculus terms."""
    pass

@dataclass(frozen=True)
class TVar(Term):
    name: str

    def __repr__(self) -> str:
        return self.name

@dataclass(frozen=True)
class TLam(Term):
    param: str
    body: Term

    def __repr__(self) -> str:
        return f"(λ{self.param}. {self.body})"

@dataclass(frozen=True)
class TApp(Term):
    func: Term
    arg: Term

    def __repr__(self) -> str:
        return f"({self.func} {self.arg})"

def subst(term: Term, var: str, replacement: Term) -> Term:
    """
    Substitutes 'var' with 'replacement' inside 'term'.
    Assumes no variable shadowing/capture issues for simplicity.
    """
    if isinstance(term, TVar):
        return replacement if term.name == var else term

    if isinstance(term, TApp):
        return TApp(
            subst(term.func, var, replacement),
            subst(term.arg, var, replacement)
        )

    if isinstance(term, TLam):
        if term.param == var:
            # Variable is bound by this lambda, stop substitution
            return term
        return TLam(term.param, subst(term.body, var, replacement))

    return term

def eval_term(term: Term) -> Term:
    """
    Evaluates a lambda calculus term using call-by-value strategy.
    """
    if isinstance(term, TVar):
        return term

    if isinstance(term, TLam):
        return term

    if isinstance(term, TApp):
        val_func = eval_term(term.func)
        val_arg = eval_term(term.arg)

        if isinstance(val_func, TLam):
            # Beta-reduction: substitute argument into body and evaluate result
            reduced_body = subst(val_func.body, val_func.param, val_arg)
            return eval_term(reduced_body)

        # Function part did not evaluate to a lambda (stuck)
        return TApp(val_func, val_arg)

    return term

def main():
    # Constructing: (λx. λy. x) 1 2
    # Inner: λy. x
    inner_lambda = TLam("y", TVar("x"))

    # Outer: λx. (λy. x)
    k_combinator = TLam("x", inner_lambda)

    # Apply K to 1: (λx. λy. x) 1
    app_one = TApp(k_combinator, TVar("1"))

    # Apply result to 2: ((λx. λy. x) 1) 2
    full_expression = TApp(app_one, TVar("2"))

    print(f"Expression: {full_expression}")

    result = eval_term(full_expression)

    print(f"Result:     {result}")

if __name__ == "__main__":
    main()

