pure func percentage(count: int, total: int) -> int =
  (count * 100) / total

pure func parseLevel(line: string) -> string =
  match split(line, " ") {
    _ :: _ :: level :: _ => level,
    _ => ""
  }

pure func parseMessage(line: string) -> string =
  match split(line, " ") {
    _ :: _ :: _ :: rest => join(" ", rest),
    _ => ""
  }

pure func afterPrefix(text: string, prefix: string) -> string =
  substring(text, strLength(prefix), strLength(text))

pure func extractUser(message: string) -> Option[string] =
  if startsWith(message, "User logged in: ") then Some(afterPrefix(message, "User logged in: "))
  else if startsWith(message, "User logged out: ") then Some(afterPrefix(message, "User logged out: "))
  else None

pure func insertSortedUnique(users: [string], user: string) -> [string] =
  match users {
    [] => [user],
    x :: rest => {
      let cmp = compare(user, x);
      if cmp == 0 then users
      else if cmp < 0 then user :: users
      else x :: insertSortedUnique(rest, user)
    }
  }

pure func analyzeLines(lines: [string]) -> {info: int, error: int, warning: int, users: [string]} =
  match lines {
    [] => {info: 0, error: 0, warning: 0, users: []},
    line :: rest => {
      let tail = analyzeLines(rest);
      let level = parseLevel(line);
      let message = parseMessage(line);
      let users2 = match extractUser(message) {
        Some(user) => insertSortedUnique(tail.users, user),
        None => tail.users
      };
      if level == "INFO" then {tail | info: tail.info + 1, users: users2}
      else if level == "ERROR" then {tail | error: tail.error + 1, users: users2}
      else if level == "WARNING" then {tail | warning: tail.warning + 1, users: users2}
      else {tail | users: users2}
    }
  }

