from pathlib import Path
import re
from collections import Counter


def create_log_file(path: Path) -> None:
    lines = [
        "2024-10-29 10:00:00 INFO User logged in: alice",
        "2024-10-29 10:01:15 ERROR Database connection failed",
        "2024-10-29 10:02:30 INFO User logged in: bob",
        "2024-10-29 10:03:45 WARNING High memory usage: 85%",
        "2024-10-29 10:05:00 ERROR API timeout: /users endpoint",
        "2024-10-29 10:06:15 INFO User logged out: alice",
    ]
    path.write_text("\n".join(lines) + "\n")


def parse_log(path: Path) -> list[dict]:
    entries = []
    for line in path.read_text().splitlines():
        if not line.strip():
            continue
        parts = line.split(" ", 3)
        entries.append({
            "date": parts[0],
            "time": parts[1],
            "level": parts[2],
            "message": parts[3] if len(parts) > 3 else "",
        })
    return entries


def extract_usernames(entries: list[dict]) -> list[str]:
    usernames = set()
    for entry in entries:
        match = re.search(r"User logged (?:in|out):\s+(\w+)", entry["message"])
        if match:
            usernames.add(match.group(1))
    return sorted(usernames)


def compute_statistics(entries: list[dict]) -> None:
    total = len(entries)
    level_counts = Counter(entry["level"] for entry in entries)
    usernames = extract_usernames(entries)

    print(f"Total log entries: {total}")
    for level in ["INFO", "ERROR", "WARNING"]:
        count = level_counts.get(level, 0)
        percentage = (count * 100) // total
        print(f"{level}: {count} ({percentage}%)")
    print(f"Unique users: {', '.join(usernames)}")


def main() -> None:
    log_path = Path("app.log")
    create_log_file(log_path)
    entries = parse_log(log_path)
    compute_statistics(entries)


if __name__ == "__main__":
    main()

