from typing import List, Tuple

def split(xs: List[int]) -> Tuple[List[int], List[int]]:
    mid = len(xs) // 2
    return xs[:mid], xs[mid:]

def merge(xs: List[int], ys: List[int]) -> List[int]:
    merged_list = []
    i = 0
    j = 0

    while i < len(xs) and j < len(ys):
        if xs[i] <= ys[j]:
            merged_list.append(xs[i])
            i += 1
        else:
            merged_list.append(ys[j])
            j += 1

    merged_list.extend(xs[i:])
    merged_list.extend(ys[j:])

    return merged_list

def mergeSort(xs: List[int]) -> List[int]:
    if len(xs) <= 1:
        return xs

    left_half, right_half = split(xs)

    left_sorted = mergeSort(left_half)
    right_sorted = mergeSort(right_half)

    return merge(left_sorted, right_sorted)

def main() -> None:
    data = [38, 27, 43, 3, 9, 82, 10]
    sorted_data = mergeSort(data)
