from __future__ import annotations

from dataclasses import dataclass
from typing import List, Tuple, Union


@dataclass(frozen=True)
class Num:
    value: int


@dataclass(frozen=True)
class Var:
    name: str


@dataclass(frozen=True)
class Add:
    left: "Expr"
    right: "Expr"


@dataclass(frozen=True)
class Mul:
    left: "Expr"
    right: "Expr"


@dataclass(frozen=True)
class Let:
    name: str
    value_expr: "Expr"
    body: "Expr"


Expr = Union[Num, Var, Add, Mul, Let]
Env = List[Tuple[str, int]]


def lookup(name: str, env: Env) -> int:
    for n, v in env:
        if n == name:
            return v
    raise NameError(f"Unbound variable: {name}")


def eval_expr(expr: Expr, env: Env) -> int:
    if isinstance(expr, Num):
        return expr.value
    if isinstance(expr, Var):
        return lookup(expr.name, env)
    if isinstance(expr, Add):
        return eval_expr(expr.left, env) + eval_expr(expr.right, env)
    if isinstance(expr, Mul):
        return eval_expr(expr.left, env) * eval_expr(expr.right, env)
    if isinstance(expr, Let):
        val = eval_expr(expr.value_expr, env)
        new_env = [(expr.name, val)] + env
        return eval_expr(expr.body, new_env)
    raise TypeError(f"Unknown expression type: {type(expr)}")


def main() -> None:
    program = Let(
        "x",
        Num(5),
        Let(
            "y",
            Add(Var("x"), Num(3)),
            Mul(Var("x"), Var("y")),
        ),
    )
    result = eval_expr(program, [])
    print(result)


if __name__ == "__main__":
    main()

