module benchmark/solution

type Color = Red | Black deriving (Eq)
type RBTree = Empty | Node(Color, RBTree, int, RBTree)

pure func balance(color: Color, left: RBTree, value: int, right: RBTree) -> RBTree =
  match (color, left, value, right) {
    (Black, Node(Red, Node(Red, a, x, b), y, c), z, d) => Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),
    (Black, Node(Red, a, x, Node(Red, b, y, c)), z, d) => Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),
    (Black, a, x, Node(Red, Node(Red, b, y, c), z, d)) => Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),
    (Black, a, x, Node(Red, b, y, Node(Red, c, z, d))) => Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),
    _ => Node(color, left, value, right)
  }

pure func ins(x: int, tree: RBTree) -> RBTree =
  match tree {
    Empty => Node(Red, Empty, x, Empty),
    Node(color, left, value, right) =>
      if x < value then balance(color, ins(x, left), value, right)
      else if x > value then balance(color, left, value, ins(x, right))
      else Node(color, left, value, right)
  }

pure func makeBlack(tree: RBTree) -> RBTree =
  match tree {
    Empty => Empty,
    Node(_, left, value, right) => Node(Black, left, value, right)
  }

pure func insert(x: int, tree: RBTree) -> RBTree =
  makeBlack(ins(x, tree))

pure func inorder(tree: RBTree) -> [int] =
  match tree {
    Empty => [],
    Node(_, left, value, right) => inorder(left) ++ [value] ++ inorder(right)
  }

pure func insertAll(xs: [int], tree: RBTree) -> RBTree =
  match xs {
    [] => tree,
    x :: rest => insertAll(rest, insert(x, tree))
  }

export func main() -> () ! {IO} {
  let values = [7, 3, 18, 10, 22, 8, 11, 26];
  let tree = insertAll(values, Empty);
  println(show(inorder(tree)))
}

