from dataclasses import dataclass
from typing import Union


@dataclass(frozen=True)
class Idle:
    floor: int


@dataclass(frozen=True)
class Moving:
    current_floor: int
    target_floor: int


@dataclass(frozen=True)
class DoorOpen:
    floor: int
    timer: int


State = Union[Idle, Moving, DoorOpen]


@dataclass(frozen=True)
class Call:
    floor: int


@dataclass(frozen=True)
class Tick:
    pass


@dataclass(frozen=True)
class Arrive:
    pass


Event = Union[Call, Tick, Arrive]


def transition(state: State, event: Event) -> State:
    if isinstance(state, Idle) and isinstance(event, Call):
        floor = state.floor
        target = event.floor
        if target == floor:
            return DoorOpen(floor=floor, timer=3)
        else:
            return Moving(current_floor=floor, target_floor=target)
    elif isinstance(state, Moving) and isinstance(event, Tick):
        return Moving(current_floor=state.current_floor, target_floor=state.target_floor)
    elif isinstance(state, Moving) and isinstance(event, Arrive):
        return DoorOpen(floor=state.target_floor, timer=3)
    elif isinstance(state, DoorOpen) and isinstance(event, Tick):
        if state.timer > 1:
            return DoorOpen(floor=state.floor, timer=state.timer - 1)
        else:
            return Idle(floor=state.floor)
    else:
        return state


def display(state: State) -> str:
    if isinstance(state, Idle):
        return f"IDLE @ floor {state.floor}"
    elif isinstance(state, Moving):
        return f"MOVING {state.current_floor} -> {state.target_floor}"
    elif isinstance(state, DoorOpen):
        return f"DOOR_OPEN @ floor {state.floor} ({state.timer}sec)"
    else:
        raise ValueError(f"Unknown state: {state}")


def main():
    state = Idle(floor=1)

    state = transition(state, Call(floor=5))
    print(display(state))

    for _ in range(2):
        state = transition(state, Tick())
        print(display(state))

    state = transition(state, Arrive())
    print(display(state))

    for _ in range(4):
        state = transition(state, Tick())
        print(display(state))

    state = transition(state, Call(floor=1))
    print(display(state))


if __name__ == "__main__":
    main()

