type Expr = Const(int) | Var(string) | Add(Expr, Expr) | Mul(Expr, Expr)

pure func diff(expr: Expr, v: string) -> Expr =
  match expr {
    Const(_) => Const(0),
    Var(name) => if name == v then Const(1) else Const(0),
    Add(a, b) => Add(diff(a, v), diff(b, v)),
    Mul(a, b) => Add(Mul(a, diff(b, v)), Mul(b, diff(a, v)))
  }

pure func simplify(expr: Expr) -> Expr =
  match expr {
    Const(n) => Const(n),
    Var(name) => Var(name),
    Add(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), e) => e,
        (e, Const(0)) => e,
        _ => Add(sa, sb)
      }
    },
    Mul(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), _) => Const(0),
        (_, Const(0)) => Const(0),
        (Const(1), e) => e,
        (e, Const(1)) => e,
        _ => Mul(sa, sb)
      }
    }
  }

pure func showExpr(expr: Expr) -> string =
  match expr {
    Const(n) => show(n),
    Var(name) => name,
    Add(a, b) => "(" ++ showExpr(a) ++ " + " ++ showExpr(b) ++ ")",
    Mul(a, b) => "(" ++ showExpr(a) ++ " * " ++ showExpr(b) ++ ")"
  }

