from typing import Union, Callable, Any, List

class Leaf:
    def __init__(self, value: int):
        self.value = value

class Node:
    def __init__(self, left: 'Tree', value: int, right: 'Tree'):
        self.left = left
        self.value = value
        self.right = right

Tree = Union[Leaf, Node]

def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    elif isinstance(tree, Node):
        return Node(
            mapTree(fn, tree.left),
            fn(tree.value),
            mapTree(fn, tree.right)
        )
    raise TypeError("Invalid tree node")

def foldTree(fn: Callable[[Any, int], Any], acc: Any, tree: Tree) -> Any:
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    elif isinstance(tree, Node):
        acc = foldTree(fn, acc, tree.left)
        acc = fn(acc, tree.value)
        return foldTree(fn, acc, tree.right)
    raise TypeError("Invalid tree node")

def treeToList(tree: Tree) -> List[int]:
    if isinstance(tree, Leaf):
        return [tree.value]
    elif isinstance(tree, Node):
        return treeToList(tree.left) + [tree.value] + treeToList(tree.right)
    raise TypeError("Invalid tree node")

def treeDepth(tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return 1
    elif isinstance(tree, Node):
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))
    raise TypeError("Invalid tree node")

def main():
    tree = Node(
        Node(Leaf(1), 2, Leaf(3)),
        4,
        Node(Leaf(5), 6, Leaf(7))
    )

    print(treeToList(tree))
    print(treeToList(mapTree(lambda x: x * 2, tree)))
    print(foldTree(lambda acc, x: acc + x, 0, tree))
    print(treeDepth(tree))

if __name__ == "__main__":
    main()

